-- SPLIT-3B local/public data seed for ImmigratiImprenditori
-- Source: read-only snapshot of the existing Supabase project on 2026-08-17.
-- Scope intentionally excludes auth.users, profiles, accounts and all PonteImprese domains.
-- Expected rows: contents=18, observatory_indicators=1,
-- observatory_statistical_sources=1, observatory_indicator_values=6.

begin;

with payload as (
  select convert_from(decode(
'',
'base64'),'UTF8')::jsonb as data
)
insert into public.contents
select * from jsonb_populate_recordset(null::public.contents, (select data from payload));

with payload as (
  select convert_from(decode(
'',
'base64'),'UTF8')::jsonb as data
)
insert into public.observatory_indicators
select * from jsonb_populate_recordset(null::public.observatory_indicators, (select data from payload));

with payload as (
  select convert_from(decode(
'',
'base64'),'UTF8')::jsonb as data
)
insert into public.observatory_statistical_sources
select * from jsonb_populate_recordset(null::public.observatory_statistical_sources, (select data from payload));

with payload as (
  select convert_from(decode(
'',
'base64'),'UTF8')::jsonb as data
)
insert into public.observatory_indicator_values
select * from jsonb_populate_recordset(null::public.observatory_indicator_values, (select data from payload));

do $$
begin
  if (select count(*) from public.contents) <> 18 then
    raise exception 'SPLIT-3 seed assertion failed: contents count';
  end if;
  if (select count(*) from public.observatory_indicators) <> 1 then
    raise exception 'SPLIT-3 seed assertion failed: observatory_indicators count';
  end if;
  if (select count(*) from public.observatory_statistical_sources) <> 1 then
    raise exception 'SPLIT-3 seed assertion failed: observatory_statistical_sources count';
  end if;
  if (select count(*) from public.observatory_indicator_values) <> 6 then
    raise exception 'SPLIT-3 seed assertion failed: observatory_indicator_values count';
  end if;
end;
$$;

commit;
